<script setup>
import { computed, onBeforeUnmount, onMounted, reactive, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { Clock3, LockKeyhole, Wifi } from 'lucide-vue-next'
import { useAuthStore } from '../stores/auth.js'
import { useRoomStore } from '../stores/room.js'
import { lockRound, saveAnswers, stopRoundNow, watchMyAnswer, watchRound } from '../services/game.js'
import CharacterAvatar from '../components/common/CharacterAvatar.vue'
import { answerCompletion } from '../utils/completion.js'
import { audioManager } from '../audio/manager.js'
import { countdownCue } from '../audio/countdown.js'

const route=useRoute(),router=useRouter(),auth=useAuthStore(),roomStore=useRoomStore(); const round=ref(null),answers=reactive({}),now=ref(Date.now()),error=ref(''),confirmStop=ref(false),stopping=ref(false),saveState=ref('saved'),stopOverlay=ref(false),activeCategory=ref(0),answerInputs=ref([]);let stopRound,tick,saveTimer,transitionTimer,previousSecond=null,completionWas=false,answerHydrated=false
const code=computed(()=>String(route.params.code).toUpperCase()),roundId=computed(()=>String(route.params.roundId));const remaining=computed(()=>Math.max(0,Math.ceil(((round.value?.deadline?.toMillis?.()||0)-now.value)/1000)));const formatted=computed(()=>`${String(Math.floor(remaining.value/60)).padStart(2,'0')}:${String(remaining.value%60).padStart(2,'0')}`);let stopAnswer,locking=false
const stoppingPlayer=computed(()=>roomStore.players.find(player=>player.uid===round.value?.stoppedBy))
const categories=computed(()=>roomStore.room?.categories||[]),completion=computed(()=>answerCompletion(categories.value,answers)),completionPercent=computed(()=>completion.value.total?completion.value.completed/completion.value.total*100:0)
onMounted(async()=>{await auth.initialize();roomStore.subscribe(code.value);stopAnswer=watchMyAnswer(code.value,roundId.value,auth.uid,value=>{if(value?.values)Object.assign(answers,value.values);completionWas=completion.value.isComplete;answerHydrated=true;if(completionWas)audioManager.mark(`complete:${code.value}:${roundId.value}:${auth.uid}`)},e=>error.value=e.message);stopRound=watchRound(code.value,roundId.value,value=>{round.value=value;if(value?.status==='answering'){const started=value.startedAt?.toMillis?.()||0;if(Date.now()-started<3000)audioManager.playOnce('roundStart',`round-start:${code.value}:${roundId.value}`)}else audioManager.stopTimer();if(value?.status==='reviewing'||value?.status==='finalized'){clearTimeout(saveTimer);if(value.stopReason==='harfana'){audioManager.playOnce('harfana',`harfana:${code.value}:${roundId.value}`);stopOverlay.value=true;transitionTimer=setTimeout(()=>router.replace(`/room/${code.value}/round/${roundId.value}/review`),1400)}else router.replace(`/room/${code.value}/round/${roundId.value}/review`)}},e=>error.value=e.message);tick=setInterval(()=>now.value=Date.now(),500)})
onBeforeUnmount(()=>{roomStore.cleanup();stopRound?.();stopAnswer?.();audioManager.stopTimer();clearInterval(tick);clearTimeout(saveTimer);clearTimeout(transitionTimer)})
watch(answers,()=>{clearTimeout(saveTimer);if(round.value?.status==='answering'&&remaining.value>0){saveState.value='saving';saveTimer=setTimeout(async()=>{try{await saveAnswers(code.value,roundId.value,auth.uid,{...answers});saveState.value='saved'}catch(e){saveState.value='error';error.value=e.message}},500)}},{deep:true})
watch(remaining,async value=>{const cue=countdownCue({previous:previousSecond,current:value,status:round.value?.status,visible:!document.hidden});previousSecond=value;if(cue)audioManager.playOnce(cue,`timer:${code.value}:${roundId.value}:${value}`);if(value===0&&round.value?.status==='answering'&&!locking){locking=true;try{await lockRound(code.value,roundId.value)}catch(e){if(!String(e.message).includes('failed-precondition'))error.value=e.message}finally{locking=false}}})
watch(()=>completion.value.isComplete,value=>{if(answerHydrated&&value&&!completionWas)audioManager.playOnce('complete',`complete:${code.value}:${roundId.value}:${auth.uid}`);completionWas=value})
function focusCategory(index){activeCategory.value=Math.max(0,Math.min(index,categories.value.length-1));requestAnimationFrame(()=>answerInputs.value[activeCategory.value]?.focus())}
function nextCategory(index){if(index<categories.value.length-1)focusCategory(index+1)}
function openStopConfirm(){if(!completion.value.isComplete){focusCategory(categories.value.indexOf(completion.value.missing[0]));return}confirmStop.value=true}
async function confirmHarfana(){if(!completion.value.isComplete){confirmStop.value=false;focusCategory(categories.value.indexOf(completion.value.missing[0]));return}clearTimeout(saveTimer);confirmStop.value=false;stopping.value=true;error.value='';try{await stopRoundNow(code.value,roundId.value,{...answers});saveState.value='saved'}catch(e){error.value=e?.message||'معرفناش نقفل الجولة.'}finally{stopping.value=false}}
</script>
<template><div class="game-demo"><header class="game-header"><RouterLink :to="`/room/${code}`" class="back-link light">القعدة</RouterLink><div class="round-label"><small>الجولة</small><b>{{ round?.number||1 }} <i>/ {{ roomStore.room?.totalRounds }}</i></b></div><div class="timer"><Clock3/><b dir="ltr">{{ formatted }}</b></div><div class="connection"><Wifi/> متصل</div></header>
<section v-if="round" class="round-hero"><div><span>حرف الجولة</span><b>{{ round.letter }}</b></div><p>{{ remaining ? 'اكتب أسرع ما عندك.. بس خليك حرفنجي!' : 'الأقلام اترفعت!' }}</p><div class="save-pill" :class="saveState"><i></i>{{saveState==='saving'?'بنحفظ...':saveState==='error'?'الحفظ وقف':'الإجابات محفوظة'}}</div></section><main class="notebook-wrap"><section class="player-status-strip"><article v-for="player in roomStore.players" :key="player.uid" :class="{me:player.uid===auth.uid}"><CharacterAvatar :id="player.avatar" :size="38"/><span>{{player.nickname}}</span><i :class="{online:player.connected}"></i><small v-if="player.uid===auth.uid">{{completion.completed}}/{{completion.total}}</small></article></section><section class="notebook"><div class="spiral"><i v-for="n in 11" :key="n"/></div><div class="notebook-progress"><span>كمّلت <b>{{completion.completed}} / {{completion.total}}</b></span><div><i :style="{width:`${completionPercent}%`}"></i></div><small v-if="completion.missing.length">ناقص {{completion.missing.length}} إجابة</small><small v-else class="complete-copy">الكشكول كامل! جاهز للحرفنة</small></div><nav class="mobile-category-nav"><button v-for="(category,index) in categories" :key="category" :class="{active:activeCategory===index,done:!completion.missing.includes(category)}" @click="focusCategory(index)">{{index+1}}</button></nav><div v-if="round?.status==='answering'&&remaining" class="live-answer-grid"><label v-for="(category,index) in categories" :key="category" :class="[`color-border-${index%4}`,{incomplete:completion.missing.includes(category),'mobile-active':activeCategory===index}]"><span>{{ category }}</span><input :ref="el=>answerInputs[index]=el" v-model="answers[category]" maxlength="80" :placeholder="`اكتب ${category} بحرف ${round.letter}`" @focus="activeCategory=index" @keydown.enter.prevent="nextCategory(index)"/></label><label class="total-preview"><span>المجموع</span><output>—</output><small>بعد التصحيح</small></label></div><div v-else class="round-locked"><LockKeyhole/><h2>الجولة اتقفلت</h2><p>استنى الأدمن يراجع الكراسات.</p></div><p v-if="error" class="error-message">{{ error }}</p></section><aside v-if="roomStore.room?.instantStopEnabled!==false&&round?.status==='answering'&&remaining" class="harfana-action" :class="{unlocked:completion.isComplete}"><div><b>{{completion.isComplete?'كله تمام.. جاهز؟':'كمّل الكشكول الأول'}}</b><span>{{completion.isComplete?'اقفل الجولة عند الكل!':`لسه ${completion.missing.length} إجابة ناقصة`}}</span></div><button :disabled="stopping||!completion.isComplete" @click="openStopConfirm">{{stopping?'بنقفل...':'حرفنة!'}}</button><small>{{completion.isComplete?'آخر تعديلاتك هتتحفظ لحظة القفل':'المجموع مش بيتحسب ضمن الإجابات'}}</small></aside></main>
<Transition name="fade"><div v-if="confirmStop" class="modal-backdrop" @click.self="confirmStop=false"><section class="modal-card stop-confirm"><span class="stop-pencil">✏️</span><h2>متأكد إنك خلصت؟</h2><p>الجولة هتقفل عند كل اللاعبين فورًا!</p><div><button class="btn btn-primary" @click="confirmHarfana">أيوه، حرفنة!</button><button class="btn btn-soft" @click="confirmStop=false">لسه بكتب</button></div></section></div></Transition>
<Transition name="fade"><div v-if="stopOverlay" class="stop-overlay"><div class="confetti-bits"><i v-for="n in 12" :key="n"/></div><span class="flying-pencil">✏️</span><h2>حرفنة!</h2><CharacterAvatar :id="stoppingPlayer?.avatar" :size="86"/><p><b>{{stoppingPlayer?.nickname||'حد من الحرفنجية'}}</b> خلّص الأول وقفّل الجولة!</p></div></Transition></div></template>
